{
			idMap.invalidateCache(all);

			foreach (AbstractDBTraceSymbolSingleTypeView<object> view in symbolViews.values()) {
				view.invalidateCache();
			}

			if (globalNamespace.isDeleted()) {
				throw new AssertionError();
			}
		}
	}

